const data = {};
for (let i = 0; i < localStorage.length; i++) {
const k = localStorage.key(i);
if (k && k.startsWith("ether.") && !k.startsWith("ether.sec.") && !RATCHET_STATE_KEYS.includes(k)) data[k] = localStorage.getItem(k);
}
let payload = data;
let password = null;
